scwin.gScnNm;
X < !공시상세--;
목록검색;
클릭-- > async function() {
    const vIsurCd = txb_isur_cd.getValue();
    const vIcnb_lst_yn = chb_lst_yn.getValue();
    const vIcnb_ldxAct_yn = chb_IdxAct_yn.getValue();

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    // 조회일 구분
    if (scwin.getChkValue(chb_lst_yn) === 0 && scwin.getChkValue(chb_IdxAct_yn) === 0) {
        await $c.win.alert("조회공시선택은 한개이상 선택하십시오.");
        chb_lst_yn.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    fn_Search();
} < !공시상세--;
클릭-- > async function() {
    const url = "";
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/IdxDisclosureSearch.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.resetParam();

        // fn_CheckCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26900.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        fn_CheckCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26900.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.dts_DsclList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_sDate_OnLoadError
 * @description dts_sDate 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_sDate_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_sDate);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26900.dts_sDate_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_sDate_OnLoadCompleted
 * @description dts_sDate 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_sDate_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_sDate.getCellData(0, "SDATE_DD") === "") {
            const vCurDate = $c.ut.cGetToday("yyyymmdd");
            // edt_FromDate.text = cGetMinusDate2(vCurDate, 7);     // 일주일전 날짜
            edt_FromDate.setValue(vCurDate); // 현재날짜
            edt_ToDate.setValue(vCurDate); // 현재날짜

        } else {
            edt_FromDate.setValue(dts_sDate.getCellData(0, "SDATE_DD"));
            edt_ToDate.setValue(dts_sDate.getCellData(0, "SDATE_DD"));
        }
        fn_Search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.dts_sDate_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        // Grd_com_isur.style.display ="";
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "지수공시상세검색 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Snd_onclick
 * @description 「조회대상공시」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Snd_onclick = function() {
    try {
        location.href = "/dsclsrch/idxDsclsrch.xls";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.btn_Snd_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26900.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Grid_onlbuttondblclk
 * @description grd_Grid onlbuttondblclk 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} xpos xpos
 * @param {*} ypos ypos
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_onlbuttondblclk = async function(row, colid, xpos, ypos) {
    try {
        scwin.setContnId(row);
        if (colid === "DISCLS_NM") {
            // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF26900.xml');
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26900.grd_Grid_onlbuttondblclk" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description get Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_sDate",
        action : "/IdxDisclosureSearch.do",
        ref : "",
        target : "dts_sDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ShowWin(grd_Grid);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};

/**
 * @method
 * @name resetParam
 * @description reset Param 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.resetParam = async function() {
    vCurrDate = await scwin.getDate();
    txb_isur_cd.setValue("");
    txb_com_abbrv.setValue("");
    scwin.setChkValue(chb_IdxAct_yn, true);
    scwin.setChkValue(chb_lst_yn, true);
    rdo_DSCL_ID.setValue("2");
    dts_DsclList.removeAll();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
